const N = 1000;
const fila = i => {
  const li = document.createElement('li');
  li.innerHTML = `Pedido ${i} <button data-pedido="${i}"><span>Entregar</span></button>`;
  return li;
};
const A = document.getElementById('a');
const B = document.getElementById('b');
const registro = [];

// Forma A: un manejador por botón
for (let i = 0; i < N; i++) {
  const li = fila(i);
  li.querySelector('button').addEventListener('click', () => registro.push('A:' + i));
  A.append(li);
}

// Forma B: un solo manejador en la lista, que mira quién fue el objetivo
for (let i = 0; i < N; i++) B.append(fila(i));
B.addEventListener('click', e => {
  const boton = e.target.closest('button[data-pedido]');
  if (!boton || !B.contains(boton)) return;       // el clic fue en otra parte de la lista
  registro.push('B:' + boton.dataset.pedido);
});

// Una fila nueva en cada lista, creada DESPUÉS de registrar los manejadores
A.append(fila('nuevo'));
B.append(fila('nuevo'));
window.registro = registro;

const { chromium } = require('/opt/node22/lib/node_modules/playwright');
(async () => {
  const b = await chromium.launch();
  for (const modo of ['A', 'B', 'A', 'B']) {
    const p = await b.newPage();
    await p.setContent('<!doctype html><ul id="u"></ul>');
    const cdp = await p.context().newCDPSession(p);
    await cdp.send('HeapProfiler.enable');
    await cdp.send('HeapProfiler.collectGarbage');
    const antes = (await cdp.send('Runtime.getHeapUsage')).usedSize;
    await p.evaluate((modo) => {
      const u = document.getElementById('u'); const N = 20000; const reg = [];
      for (let i = 0; i < N; i++) {
        const li = document.createElement('li'); const bt = document.createElement('button'); bt.textContent = 'Entregar ' + i; li.append(bt); u.append(li);
        if (modo === 'A') bt.addEventListener('click', () => reg.push(i));
      }
      if (modo === 'B') u.addEventListener('click', e => { const t = e.target.closest('button'); if (t) reg.push(t.textContent); });
      window.__u = u;
    }, modo);
    await cdp.send('HeapProfiler.collectGarbage');
    const despues = (await cdp.send('Runtime.getHeapUsage')).usedSize;
    console.log(modo, ((despues - antes) / 1048576).toFixed(1), 'MiB de heap de JS');
    await p.close();
  }
  await b.close();
})();

